private refill(now: number): void {
  const elapsed = now - this.lastRefill;
  const intervals = Math.ceil(elapsed / this.intervalMs);
  this.tokens = Math.min(this.capacity, this.tokens + intervals * this.refillRate);
  this.lastRefill = now;
}

